(27,'system_maintenance_scheduled','Plánovaná údržba systému','','Dobrý den,\n\nplánovaná údržba systému proběhne:\n\n',1,'Plánovaná údržba systému: {maintenance_date}','Údržba systému: {maintenance_date} od {start_time} do {end_time}. Systém bude nedostupný.','high',1,'2025-10-29 20:46:18','2025-11-05 21:46:38'),
(28,'system_maintenance_starting','Údržba systému začíná','','Dobrý den,\n\núdržba systému právě začíná.\n\n⏰ Aktuální čas: {current_time}\n⏱️ Předpokládané trvání: {duration} minut\n\n⚠️ Systém bude během této doby nedostupný.\n\nDěkujeme za trpělivost.\n\nS pozdravem,\nSystém EEO',1,'Údržba systému právě začíná','Systém přechází do režimu údržby. Předpokládané trvání: {duration} minut.','urgent',1,'2025-10-29 20:46:18','2025-11-05 21:46:38'),
(29,'system_maintenance_finished','Údržba systému dokončena','✅ Údržba systému byla dokončena','Dobrý den,\n\núdržba systému byla úspěšně dokončena.\n\n⏰ Čas dokončení: {finish_time}\n⏱️ Trvání: {actual_duration} minut\n\n✅ Systém je opět plně funkční.\n\nDěkujeme za trpělivost.\n\nS pozdravem,\nSystém EEO',1,'✅ Údržba dokončena','Systém je opět plně funkční. Údržba dokončena v {finish_time}.','normal',1,'2025-10-29 20:46:18',NULL),
(30,'system_backup_completed','Automatické zálohování dokončeno','','Automatické zálohování systému bylo úspěšně dokončeno.\n\n⏰ Čas: {backup_time}\n',0,'Automatická záloha dokončena','Záloha systému vytvořena ({backup_size}). Další záloha: {next_backup}.','low',1,'2025-10-29 20:46:18','2025-11-05 21:46:38'),
