(38,'deadline_reminder','Upozornění na blížící se termín','⏰ Blíží se termín objednávky {order_number}','Dobrý den,\n\nblíží se termín dodání objednávky:\n\n',1,'⏰ Blíží se termín','Objednávka {order_number} má termín dodání {deadline_date}. Zbývá {days_remaining} dní.','high',1,'2025-10-29 20:46:18',NULL),
(39,'order_unlock_forced','Objednávka násilně odemknuta','','Dobrý den,\n\nobjednávka, kterou jste měli zamčenou, byla násilně odemknuta:\n\n',1,'Násilně odemknuta: {order_number}','Objednávka {order_number} byla násilně odemknuta uživatelem {unlocked_by}. Důvod: {unlock_reason}','high',1,'2025-10-29 20:46:18','2025-11-05 21:46:38'),
